CREATE OR REPLACE FUNCTION commercial.assert_subscription_usage_period()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target_subscription_id uuid; subscription_status text; period_start timestamptz; period_end timestamptz; matching_open integer;
BEGIN
 IF TG_TABLE_NAME = 'subscriptions' THEN
   target_subscription_id := COALESCE(to_jsonb(NEW)->>'id', to_jsonb(OLD)->>'id')::uuid;
 ELSE
   target_subscription_id := COALESCE(to_jsonb(NEW)->>'subscription_id', to_jsonb(OLD)->>'subscription_id')::uuid;
 END IF;
 SELECT status, current_period_start, current_period_end INTO subscription_status, period_start, period_end
 FROM commercial.subscriptions WHERE id = target_subscription_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT count(*) INTO matching_open FROM commercial.usage_periods
 WHERE subscription_id = target_subscription_id AND status = 'open'
   AND starts_at IS NOT DISTINCT FROM period_start AND ends_at IS NOT DISTINCT FROM period_end;
 IF subscription_status = 'active' AND matching_open <> 1 THEN
   RAISE EXCEPTION 'active subscription requires one matching open usage period' USING ERRCODE = 'check_violation';
 END IF;
 IF subscription_status <> 'active' AND EXISTS (SELECT 1 FROM commercial.usage_periods WHERE subscription_id = target_subscription_id AND status = 'open') THEN
   RAISE EXCEPTION 'terminal or draft subscription cannot have an open usage period' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_cloud_system_domain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE domain_count integer;
BEGIN
 IF NEW.mode <> 'on_prem' THEN
   SELECT count(*) INTO domain_count FROM commercial.deployment_domains WHERE deployment_id = NEW.id AND kind = 'system';
   IF domain_count <> 1 THEN RAISE EXCEPTION 'cloud deployment requires one system domain' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_invoice_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE subscription_account uuid; subscription_status text; profile_account uuid; line_count integer; line_sum numeric;
BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'invoices are historical and cannot be deleted' USING ERRCODE = 'check_violation'; END IF;
 SELECT commercial_account_id, status INTO subscription_account, subscription_status FROM commercial.subscriptions WHERE id = NEW.subscription_id FOR UPDATE;
 SELECT commercial_account_id INTO profile_account FROM commercial.billing_profiles WHERE id = NEW.billing_profile_id FOR UPDATE;
 IF subscription_account IS DISTINCT FROM NEW.commercial_account_id OR profile_account IS DISTINCT FROM NEW.commercial_account_id THEN
   RAISE EXCEPTION 'invoice account contract mismatch' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'INSERT' AND NEW.billing_reason = 'subscription_renewal' AND subscription_status IS DISTINCT FROM 'active' THEN
   RAISE EXCEPTION 'renewal invoice requires an active subscription' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'UPDATE' THEN
   IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'invoice creation timestamp is immutable' USING ERRCODE = 'check_violation'; END IF;
   IF OLD.status <> 'draft' AND (
     NEW.commercial_account_id, NEW.subscription_id, NEW.billing_profile_id, NEW.billing_reason,
     NEW.service_period_start, NEW.service_period_end, NEW.currency, NEW.total_minor,
     NEW.bill_to_legal_name, NEW.bill_to_country_code, NEW.bill_to_contact_name,
     NEW.bill_to_contact_email, NEW.bill_to_tax_identifier, NEW.bill_to_address,
     NEW.created_at, NEW.issued_at
   ) IS DISTINCT FROM (
     OLD.commercial_account_id, OLD.subscription_id, OLD.billing_profile_id, OLD.billing_reason,
     OLD.service_period_start, OLD.service_period_end, OLD.currency, OLD.total_minor,
     OLD.bill_to_legal_name, OLD.bill_to_country_code, OLD.bill_to_contact_name,
     OLD.bill_to_contact_email, OLD.bill_to_tax_identifier, OLD.bill_to_address,
     OLD.created_at, OLD.issued_at
   ) THEN RAISE EXCEPTION 'issued invoice snapshot is immutable' USING ERRCODE = 'check_violation'; END IF;
   IF NEW.status <> OLD.status AND NOT ((OLD.status = 'draft' AND NEW.status IN ('issued','void')) OR (OLD.status = 'issued' AND NEW.status IN ('paid','void'))) THEN
     RAISE EXCEPTION 'invalid invoice status transition' USING ERRCODE = 'check_violation';
   END IF;
   IF OLD.status IN ('paid','void') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal invoice is immutable' USING ERRCODE = 'check_violation'; END IF;
   IF OLD.status = 'draft' AND NEW.status = 'issued' THEN
     SELECT count(*), COALESCE(sum(total_minor), 0) INTO line_count, line_sum FROM commercial.invoice_lines WHERE invoice_id = NEW.id;
     IF line_count < 1 OR line_sum <> NEW.total_minor THEN RAISE EXCEPTION 'issued invoice lines and total are inconsistent' USING ERRCODE = 'check_violation'; END IF;
   END IF;
   IF OLD.status = 'issued' AND NEW.status = 'paid' AND NOT EXISTS (
     SELECT 1 FROM commercial.payments p WHERE p.invoice_id = NEW.id AND p.status = 'succeeded'
       AND p.commercial_account_id = NEW.commercial_account_id AND p.amount_minor = NEW.total_minor AND p.currency = NEW.currency
   ) THEN RAISE EXCEPTION 'paid invoice requires a matching succeeded payment' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_invoice_line_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE invoice_status text; invoice_subscription uuid; old_invoice_status text;
BEGIN
 SELECT status, subscription_id INTO invoice_status, invoice_subscription
 FROM commercial.invoices WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END FOR UPDATE;
 IF invoice_status IS DISTINCT FROM 'draft' THEN
   RAISE EXCEPTION 'issued invoice lines are immutable' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'UPDATE' AND NEW.invoice_id <> OLD.invoice_id THEN
   SELECT status INTO old_invoice_status FROM commercial.invoices WHERE id = OLD.invoice_id FOR UPDATE;
   IF old_invoice_status IS DISTINCT FROM 'draft' THEN
     RAISE EXCEPTION 'issued invoice lines are immutable' USING ERRCODE = 'check_violation';
   END IF;
 END IF;
 IF TG_OP <> 'DELETE' AND NOT EXISTS (
   SELECT 1 FROM commercial.subscription_items si
   WHERE si.id = NEW.subscription_item_id AND si.subscription_id = invoice_subscription AND si.plan_price_id = NEW.plan_price_id
 ) THEN
   RAISE EXCEPTION 'invoice line subscription contract mismatch' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_license_installation_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE max_allowed integer; active_count integer; license_status text;
BEGIN
 SELECT max_installations, status INTO max_allowed, license_status FROM commercial.licenses WHERE id = NEW.license_id FOR UPDATE;
 IF license_status <> 'active' THEN RAISE EXCEPTION 'license is not active' USING ERRCODE = 'check_violation'; END IF;
 IF NEW.revoked_at IS NULL THEN
   SELECT count(*) INTO active_count FROM commercial.license_installations WHERE license_id = NEW.license_id AND revoked_at IS NULL AND installation_id <> NEW.installation_id;
   IF active_count >= max_allowed THEN RAISE EXCEPTION 'license installation limit exceeded' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_license_limit_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE active_count integer;
BEGIN
 IF NEW.max_installations < OLD.max_installations THEN
   SELECT count(*) INTO active_count FROM commercial.license_installations WHERE license_id = NEW.id AND revoked_at IS NULL;
   IF NEW.max_installations < active_count THEN RAISE EXCEPTION 'license installation limit exceeded' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_payment_attempt_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE payment_status text; provider_status text;
BEGIN
 IF TG_OP = 'DELETE' THEN
   RAISE EXCEPTION 'payment attempts are historical and cannot be deleted' USING ERRCODE = 'check_violation';
 END IF;
 SELECT status INTO payment_status FROM commercial.payments WHERE id = NEW.payment_id FOR UPDATE;
 IF TG_OP = 'INSERT' THEN
   SELECT status INTO provider_status FROM commercial.payment_provider_accounts WHERE id = NEW.provider_account_id FOR UPDATE;
   IF payment_status IS DISTINCT FROM 'pending' OR provider_status IS DISTINCT FROM 'active' THEN
     RAISE EXCEPTION 'new attempt requires pending payment and active provider account' USING ERRCODE = 'check_violation';
   END IF;
 ELSE
   IF (NEW.payment_id, NEW.provider_account_id, NEW.method_type, NEW.provider_request_key, NEW.created_at)
      IS DISTINCT FROM (OLD.payment_id, OLD.provider_account_id, OLD.method_type, OLD.provider_request_key, OLD.created_at) THEN
     RAISE EXCEPTION 'payment attempt identity is immutable' USING ERRCODE = 'check_violation';
   END IF;
   IF OLD.provider_payment_id IS NOT NULL AND NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id THEN
     RAISE EXCEPTION 'provider payment reference is immutable' USING ERRCODE = 'check_violation';
   END IF;
   IF NEW.status <> OLD.status AND NOT (OLD.status = 'pending' AND NEW.status IN ('succeeded','failed','cancelled')) THEN
     RAISE EXCEPTION 'invalid payment attempt transition' USING ERRCODE = 'check_violation';
   END IF;
   IF OLD.status IN ('succeeded','failed','cancelled') AND NEW IS DISTINCT FROM OLD THEN
     RAISE EXCEPTION 'terminal payment attempt is immutable' USING ERRCODE = 'check_violation';
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_payment_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE invoice_account uuid; invoice_amount bigint; invoice_currency text;
BEGIN
 IF TG_OP = 'DELETE' THEN
   RAISE EXCEPTION 'payments are historical and cannot be deleted' USING ERRCODE = 'check_violation';
 END IF;
 SELECT commercial_account_id, total_minor, currency INTO invoice_account, invoice_amount, invoice_currency
 FROM commercial.invoices WHERE id = NEW.invoice_id FOR UPDATE;
 IF invoice_account IS DISTINCT FROM NEW.commercial_account_id
    OR invoice_amount IS DISTINCT FROM NEW.amount_minor
    OR invoice_currency IS DISTINCT FROM NEW.currency THEN
   RAISE EXCEPTION 'payment must match invoice account and money' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'UPDATE' THEN
   IF (NEW.invoice_id, NEW.commercial_account_id, NEW.amount_minor, NEW.currency, NEW.created_at)
      IS DISTINCT FROM (OLD.invoice_id, OLD.commercial_account_id, OLD.amount_minor, OLD.currency, OLD.created_at) THEN
     RAISE EXCEPTION 'payment financial identity is immutable' USING ERRCODE = 'check_violation';
   END IF;
   IF NEW.status <> OLD.status AND NOT (OLD.status = 'pending' AND NEW.status IN ('succeeded','cancelled')) THEN
     RAISE EXCEPTION 'invalid payment status transition' USING ERRCODE = 'check_violation';
   END IF;
   IF OLD.status IN ('succeeded','cancelled') AND NEW IS DISTINCT FROM OLD THEN
     RAISE EXCEPTION 'terminal payment is immutable' USING ERRCODE = 'check_violation';
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_plan_child()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE plan_state text; feature_type text; feature_usage_mode text;
BEGIN
 SELECT status INTO plan_state FROM commercial.plans WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.plan_id ELSE NEW.plan_id END FOR UPDATE;
 IF plan_state <> 'draft' THEN RAISE EXCEPTION 'published plan terms are immutable' USING ERRCODE = 'check_violation'; END IF;
 IF TG_OP = 'UPDATE' AND NEW.plan_id <> OLD.plan_id THEN
   SELECT status INTO plan_state FROM commercial.plans WHERE id = OLD.plan_id FOR UPDATE;
   IF plan_state <> 'draft' THEN RAISE EXCEPTION 'published plan terms are immutable' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 IF TG_TABLE_NAME = 'plan_features' AND TG_OP <> 'DELETE' THEN
   SELECT value_type, usage_mode INTO feature_type, feature_usage_mode FROM commercial.features WHERE id = NEW.feature_id;
   IF feature_type = 'boolean' AND jsonb_typeof(NEW.value) <> 'boolean'
      OR feature_type = 'integer' AND (jsonb_typeof(NEW.value) <> 'number' OR NEW.value::text !~ '^-?[0-9]+$')
      OR feature_type = 'string' AND jsonb_typeof(NEW.value) <> 'string'
      OR feature_type = 'json' AND jsonb_typeof(NEW.value) = 'null'
   THEN RAISE EXCEPTION 'feature value type mismatch' USING ERRCODE = 'check_violation'; END IF;
   IF feature_usage_mode <> 'none' AND (NEW.value::text)::numeric NOT BETWEEN 0 AND 9223372036854775807 THEN
     RAISE EXCEPTION 'metered feature limit must fit a nonnegative bigint' USING ERRCODE = 'check_violation';
   END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_receipt_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; a record; pa record; rf record;
BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'receipts are historical and cannot be deleted' USING ERRCODE = 'check_violation'; END IF;
 IF TG_OP = 'UPDATE' THEN
   IF (NEW.payment_id, NEW.invoice_id, NEW.commercial_account_id, NEW.payment_attempt_id, NEW.refund_id, NEW.provider_account_id, NEW.receipt_type, NEW.provider_request_key, NEW.amount_minor, NEW.currency, NEW.customer_email, NEW.customer_name, NEW.vat_code, NEW.payment_subject, NEW.payment_mode, NEW.created_at)
      IS DISTINCT FROM (OLD.payment_id, OLD.invoice_id, OLD.commercial_account_id, OLD.payment_attempt_id, OLD.refund_id, OLD.provider_account_id, OLD.receipt_type, OLD.provider_request_key, OLD.amount_minor, OLD.currency, OLD.customer_email, OLD.customer_name, OLD.vat_code, OLD.payment_subject, OLD.payment_mode, OLD.created_at) THEN RAISE EXCEPTION 'receipt financial identity is immutable' USING ERRCODE = 'check_violation'; END IF;
   IF OLD.external_receipt_id IS NOT NULL AND NEW.external_receipt_id IS DISTINCT FROM OLD.external_receipt_id THEN RAISE EXCEPTION 'provider receipt reference is immutable' USING ERRCODE = 'check_violation'; END IF;
   IF NEW.status <> OLD.status AND NOT (OLD.status = 'pending' AND NEW.status IN ('succeeded','canceled')) THEN RAISE EXCEPTION 'invalid receipt status transition' USING ERRCODE = 'check_violation'; END IF;
   IF OLD.status IN ('succeeded','canceled') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal receipt is immutable' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 SELECT * INTO p FROM commercial.payments WHERE id = NEW.payment_id;
 SELECT * INTO pa FROM commercial.payment_provider_accounts WHERE id = NEW.provider_account_id;
 IF p.status IS DISTINCT FROM 'succeeded' OR p.invoice_id IS DISTINCT FROM NEW.invoice_id OR p.commercial_account_id IS DISTINCT FROM NEW.commercial_account_id OR p.currency IS DISTINCT FROM NEW.currency THEN RAISE EXCEPTION 'receipt must match succeeded payment' USING ERRCODE = 'check_violation'; END IF;
 IF NEW.receipt_type = 'payment' THEN
   SELECT * INTO a FROM commercial.payment_attempts WHERE id = NEW.payment_attempt_id;
   IF p.amount_minor IS DISTINCT FROM NEW.amount_minor OR a.status IS DISTINCT FROM 'succeeded' OR a.payment_id IS DISTINCT FROM NEW.payment_id OR a.provider_account_id IS DISTINCT FROM NEW.provider_account_id OR a.provider_payment_id IS NULL THEN RAISE EXCEPTION 'payment receipt requires succeeded provider attempt' USING ERRCODE = 'check_violation'; END IF;
 ELSE
   SELECT * INTO rf FROM commercial.refunds WHERE id = NEW.refund_id;
   IF rf.status IS DISTINCT FROM 'succeeded' OR rf.payment_id IS DISTINCT FROM NEW.payment_id OR rf.commercial_account_id IS DISTINCT FROM NEW.commercial_account_id OR rf.provider_account_id IS DISTINCT FROM NEW.provider_account_id OR rf.amount_minor IS DISTINCT FROM NEW.amount_minor OR rf.currency IS DISTINCT FROM NEW.currency OR rf.provider_refund_id IS NULL THEN RAISE EXCEPTION 'refund receipt requires succeeded authoritative refund' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 IF TG_OP = 'INSERT' AND (pa.receipt_mode IS DISTINCT FROM 'yookassa' OR pa.receipt_vat_code IS DISTINCT FROM NEW.vat_code OR pa.receipt_payment_subject IS DISTINCT FROM NEW.payment_subject OR pa.receipt_payment_mode IS DISTINCT FROM NEW.payment_mode) THEN RAISE EXCEPTION 'receipt fiscal configuration mismatch' USING ERRCODE = 'check_violation'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_receipt_item_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r record; source record;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN RAISE EXCEPTION 'receipt items are immutable' USING ERRCODE = 'check_violation'; END IF;
 SELECT * INTO r FROM commercial.receipts WHERE id = NEW.receipt_id;
 IF r.receipt_type = 'payment' THEN
   SELECT description, quantity, unit_amount_minor, total_minor INTO source FROM commercial.invoice_lines WHERE id = NEW.invoice_line_id AND invoice_id = r.invoice_id;
 ELSE
   SELECT description, quantity, unit_amount_minor, total_minor INTO source FROM commercial.refund_items WHERE refund_id = r.refund_id AND invoice_line_id = NEW.invoice_line_id;
 END IF;
 IF r.status IS DISTINCT FROM 'pending' OR source IS NULL OR source.description IS DISTINCT FROM NEW.description OR source.quantity IS DISTINCT FROM NEW.quantity OR source.unit_amount_minor IS DISTINCT FROM NEW.unit_amount_minor OR source.total_minor IS DISTINCT FROM NEW.total_minor OR r.currency IS DISTINCT FROM NEW.currency OR r.vat_code IS DISTINCT FROM NEW.vat_code OR r.payment_subject IS DISTINCT FROM NEW.payment_subject OR r.payment_mode IS DISTINCT FROM NEW.payment_mode THEN RAISE EXCEPTION 'receipt item must match fiscal source snapshot' USING ERRCODE = 'check_violation'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_refund_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; refunded numeric;
BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'refunds are historical and cannot be deleted' USING ERRCODE = 'check_violation'; END IF;
 SELECT * INTO p FROM commercial.payments WHERE id = NEW.payment_id FOR UPDATE;
 IF p.status IS DISTINCT FROM 'succeeded' OR p.commercial_account_id IS DISTINCT FROM NEW.commercial_account_id OR p.currency IS DISTINCT FROM NEW.currency THEN
   RAISE EXCEPTION 'refund must match a succeeded payment' USING ERRCODE = 'check_violation';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM commercial.payment_attempts a WHERE a.payment_id = NEW.payment_id AND a.provider_account_id = NEW.provider_account_id AND a.status = 'succeeded') THEN
   RAISE EXCEPTION 'refund requires the succeeded payment provider account' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'UPDATE' THEN
   IF (NEW.payment_id, NEW.commercial_account_id, NEW.provider_account_id, NEW.amount_minor, NEW.currency,
       NEW.client_request_key, NEW.request_sha256, NEW.provider_request_key, NEW.created_at)
      IS DISTINCT FROM
      (OLD.payment_id, OLD.commercial_account_id, OLD.provider_account_id, OLD.amount_minor, OLD.currency,
       OLD.client_request_key, OLD.request_sha256, OLD.provider_request_key, OLD.created_at) THEN
     RAISE EXCEPTION 'refund financial identity is immutable' USING ERRCODE = 'check_violation';
   END IF;
   IF OLD.provider_refund_id IS NOT NULL AND NEW.provider_refund_id IS DISTINCT FROM OLD.provider_refund_id THEN RAISE EXCEPTION 'provider refund reference is immutable' USING ERRCODE = 'check_violation'; END IF;
   IF NEW.status <> OLD.status AND NOT (OLD.status = 'pending' AND NEW.status IN ('succeeded','canceled')) THEN RAISE EXCEPTION 'invalid refund status transition' USING ERRCODE = 'check_violation'; END IF;
   IF OLD.status IN ('succeeded','canceled') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal refund is immutable' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 IF NEW.status IN ('pending','succeeded') THEN
   SELECT COALESCE(sum(amount_minor), 0) INTO refunded FROM commercial.refunds
   WHERE payment_id = NEW.payment_id AND status IN ('pending','succeeded') AND id <> NEW.id;
   IF refunded + NEW.amount_minor > p.amount_minor THEN RAISE EXCEPTION 'refund amount exceeds refundable payment balance' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_refund_item_contract()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r record; l record;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN RAISE EXCEPTION 'refund items are immutable' USING ERRCODE = 'check_violation'; END IF;
 SELECT * INTO r FROM commercial.refunds WHERE id = NEW.refund_id;
 SELECT * INTO l FROM commercial.invoice_lines WHERE id = NEW.invoice_line_id;
 IF r.status IS DISTINCT FROM 'pending' OR l.invoice_id IS DISTINCT FROM (SELECT invoice_id FROM commercial.payments WHERE id = r.payment_id)
    OR l.description IS DISTINCT FROM NEW.description OR NEW.unit_amount_minor > l.unit_amount_minor
    OR r.currency IS DISTINCT FROM NEW.currency OR NEW.quantity > l.quantity THEN
   RAISE EXCEPTION 'refund item must match invoice snapshot' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_release_child()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE release_state text;
BEGIN
 SELECT status INTO release_state FROM commercial.releases WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.release_id ELSE NEW.release_id END FOR UPDATE;
 IF release_state <> 'draft' THEN RAISE EXCEPTION 'published release entitlements are immutable' USING ERRCODE = 'check_violation'; END IF;
 IF TG_OP = 'UPDATE' AND NEW.release_id <> OLD.release_id THEN
   SELECT status INTO release_state FROM commercial.releases WHERE id = OLD.release_id FOR UPDATE;
   IF release_state <> 'draft' THEN RAISE EXCEPTION 'published release entitlements are immutable' USING ERRCODE = 'check_violation'; END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.enforce_subscription_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status <> OLD.status AND NOT (
   (OLD.status = 'draft' AND NEW.status IN ('active','cancelled')) OR
   (OLD.status = 'active' AND NEW.status IN ('cancelled','expired'))
 ) THEN
   RAISE EXCEPTION 'invalid subscription status transition' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.ensure_membership_keeps_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE account_id uuid;
BEGIN
 account_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.commercial_account_id ELSE NEW.commercial_account_id END;
 PERFORM 1 FROM commercial.commercial_accounts WHERE id = account_id FOR UPDATE;
 IF EXISTS (SELECT 1 FROM commercial.commercial_accounts WHERE id = account_id)
    AND NOT EXISTS (
      SELECT 1 FROM commercial.commercial_account_memberships
      WHERE commercial_account_id = account_id AND role = 'owner' AND revoked_at IS NULL
    ) THEN
   RAISE EXCEPTION 'commercial account requires at least one active owner' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.ensure_new_account_has_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM commercial.commercial_accounts WHERE id = NEW.id FOR UPDATE;
 IF NOT EXISTS (
   SELECT 1 FROM commercial.commercial_account_memberships
   WHERE commercial_account_id = NEW.id AND role = 'owner' AND revoked_at IS NULL
 ) THEN
   RAISE EXCEPTION 'commercial account requires at least one active owner' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.guard_plan_change_idempotency_key()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 -- Every writer, including older application versions, must agree on one owner.
 -- The transaction advisory lock makes the existence check safe under concurrent inserts.
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.idempotency_key, 0));
 IF EXISTS (
  SELECT 1 FROM commercial.idempotency_keys k
  WHERE k.idempotency_key = NEW.idempotency_key AND k.scope <> NEW.scope
 ) THEN
  RAISE EXCEPTION 'idempotency key belongs to another operation' USING ERRCODE = 'check_violation';
 END IF;
 IF EXISTS (
  SELECT 1 FROM commercial.subscription_plan_changes c
  WHERE c.idempotency_key = NEW.idempotency_key
   AND NEW.scope <> ('subscription.plan_change.request.' || replace(c.commercial_account_id::text, '-', ''))
 ) THEN
  RAISE EXCEPTION 'idempotency key belongs to an existing plan change' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.guard_published_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'DELETE' AND OLD.status = 'published' AND current_setting('app.privacy_lifecycle', true) IS DISTINCT FROM 'on' THEN
   RAISE EXCEPTION 'published outbox event is immutable' USING ERRCODE = 'check_violation';
 END IF;
 IF TG_OP = 'UPDATE' AND OLD.status = 'published' AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'published outbox event is immutable' USING ERRCODE = 'check_violation';
 END IF;
 RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION commercial.guard_renewal_collection_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'renewal collection state is historical' USING ERRCODE = 'check_violation'; END IF;
 IF (NEW.invoice_id, NEW.commercial_account_id, NEW.subscription_id, NEW.created_at)
    IS DISTINCT FROM (OLD.invoice_id, OLD.commercial_account_id, OLD.subscription_id, OLD.created_at) THEN
   RAISE EXCEPTION 'renewal collection identity is immutable' USING ERRCODE = 'check_violation';
 END IF;
 IF NEW.attempt_count < OLD.attempt_count OR NEW.network_retry_count < OLD.network_retry_count THEN
   RAISE EXCEPTION 'renewal attempt counters cannot decrease' USING ERRCODE = 'check_violation';
 END IF;
 IF NEW.state <> OLD.state AND NOT (
   (OLD.state = 'ready' AND NEW.state IN ('collecting','payment_method_required','exhausted')) OR
   (OLD.state = 'collecting' AND NEW.state IN ('retry_wait','payment_method_required','succeeded','exhausted')) OR
   (OLD.state = 'retry_wait' AND NEW.state IN ('collecting','payment_method_required','succeeded','exhausted')) OR
   (OLD.state = 'payment_method_required' AND NEW.state IN ('ready','succeeded','exhausted'))
 ) THEN RAISE EXCEPTION 'invalid renewal collection state transition' USING ERRCODE = 'check_violation'; END IF;
 IF OLD.state IN ('succeeded','exhausted') AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'terminal renewal collection state is immutable' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.guard_subscription_plan_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'DELETE' THEN
   RAISE EXCEPTION 'plan change history cannot be deleted' USING ERRCODE = 'check_violation';
 END IF;
 IF (NEW.commercial_account_id, NEW.source_subscription_id, NEW.target_subscription_id,
     NEW.old_plan_price_id, NEW.new_plan_price_id, NEW.old_quantity, NEW.new_quantity,
     NEW.change_kind, NEW.idempotency_key, NEW.request_sha256, NEW.calculation,
     NEW.currency, NEW.proration_net_minor, NEW.amount_due_minor, NEW.period_start,
     NEW.period_end, NEW.requested_at)
    IS DISTINCT FROM
    (OLD.commercial_account_id, OLD.source_subscription_id, OLD.target_subscription_id,
     OLD.old_plan_price_id, OLD.new_plan_price_id, OLD.old_quantity, OLD.new_quantity,
     OLD.change_kind, OLD.idempotency_key, OLD.request_sha256, OLD.calculation,
     OLD.currency, OLD.proration_net_minor, OLD.amount_due_minor, OLD.period_start,
     OLD.period_end, OLD.requested_at) THEN
   RAISE EXCEPTION 'plan change calculation is immutable' USING ERRCODE = 'check_violation';
 END IF;
 IF OLD.invoice_id IS NOT NULL AND NEW.invoice_id IS DISTINCT FROM OLD.invoice_id THEN
   RAISE EXCEPTION 'plan change invoice is immutable' USING ERRCODE = 'check_violation';
 END IF;
 IF NEW.status <> OLD.status AND NOT (
   (OLD.status = 'scheduled' AND NEW.status IN ('payment_required','applied','cancelled')) OR
   (OLD.status = 'payment_required' AND NEW.status IN ('applied','cancelled','paid_unapplied'))
   OR (OLD.status = 'paid_unapplied' AND NEW.status = 'refunded')
 ) THEN
   RAISE EXCEPTION 'invalid plan change transition' USING ERRCODE = 'check_violation';
 END IF;
 IF OLD.status IN ('applied','cancelled','refunded') AND NEW IS DISTINCT FROM OLD THEN
   RAISE EXCEPTION 'terminal plan change is immutable' USING ERRCODE = 'check_violation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.prevent_published_plan_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'published plan is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status = 'published' AND NEW.status = 'retired'
       AND ROW(NEW.id, NEW.code, NEW.version, NEW.name, NEW.created_at, NEW.published_at)
           IS NOT DISTINCT FROM ROW(OLD.id, OLD.code, OLD.version, OLD.name, OLD.created_at, OLD.published_at)
       AND NEW.retired_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    IF OLD.status IN ('published', 'retired') THEN
        RAISE EXCEPTION 'published plan is immutable' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$function$

