CREATE OR REPLACE FUNCTION commercial.validate_privacy_audit_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF length(NEW.metadata::text)>512 OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.metadata) key WHERE key NOT IN ('role','reason','failure_code','deploymentId','installationId','operationId','sourceReleaseId','targetReleaseId'))
 OR EXISTS(SELECT 1 FROM jsonb_each(NEW.metadata) entry WHERE jsonb_typeof(entry.value)<>'string' OR length(entry.value #>> '{}')>80)
 THEN RAISE EXCEPTION 'audit metadata is outside privacy allowlist' USING ERRCODE='check_violation'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each_text(NEW.metadata) entry WHERE entry.key IN ('deploymentId','installationId','operationId')
   AND (NEW.action NOT IN ('deployment.decommission_requested','deployment.decommissioned','deployment.updated')
     OR entry.value !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'))
 THEN RAISE EXCEPTION 'deployment audit metadata is invalid' USING ERRCODE='check_violation'; END IF;
 IF NEW.action = 'deployment.updated' AND (
   (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(NEW.metadata) key)
     <> ARRAY['deploymentId','operationId','sourceReleaseId','targetReleaseId']::text[]
   OR EXISTS (SELECT 1 FROM jsonb_each_text(NEW.metadata) e WHERE e.value !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$')
 ) THEN RAISE EXCEPTION 'update audit metadata is invalid' USING ERRCODE='check_violation'; END IF;
 IF jsonb_exists(NEW.metadata,'role') AND (NEW.action NOT IN ('commercial_membership.saved','commercial_membership.role_changed') OR NEW.metadata->>'role' NOT IN ('owner','admin','billing','technical')) THEN RAISE EXCEPTION 'audit role metadata is invalid' USING ERRCODE='check_violation'; END IF;
 IF jsonb_exists(NEW.metadata,'reason') AND (NEW.action<>'control_session.login' OR NEW.metadata->>'reason'<>'invalid_credentials') THEN RAISE EXCEPTION 'audit reason metadata is invalid' USING ERRCODE='check_violation'; END IF;
 IF jsonb_exists(NEW.metadata,'failure_code') AND (NEW.action NOT IN ('payment.attempt.failed','refund.canceled') OR NEW.metadata->>'failure_code' !~ '^[a-z0-9]+([._-][a-z0-9]+)*$') THEN RAISE EXCEPTION 'audit failure metadata is invalid' USING ERRCODE='check_violation'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION commercial.validate_receipt_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target_receipt_id uuid; expected_count bigint; actual_count bigint; actual_total numeric; r record;
BEGIN
 IF TG_TABLE_NAME = 'receipts' THEN target_receipt_id := (to_jsonb(NEW)->>'id')::uuid;
 ELSE target_receipt_id := (to_jsonb(NEW)->>'receipt_id')::uuid; END IF;
 SELECT * INTO r FROM commercial.receipts WHERE id = target_receipt_id;
 IF r.receipt_type = 'payment' THEN SELECT count(*) INTO expected_count FROM commercial.invoice_lines WHERE invoice_id = r.invoice_id;
 ELSE SELECT count(*) INTO expected_count FROM commercial.refund_items WHERE refund_id = r.refund_id; END IF;
 SELECT count(*), COALESCE(sum(total_minor), 0) INTO actual_count, actual_total FROM commercial.receipt_items WHERE receipt_id = target_receipt_id;
 IF expected_count <> actual_count OR r.amount_minor IS DISTINCT FROM actual_total THEN RAISE EXCEPTION 'receipt item snapshot is incomplete' USING ERRCODE = 'check_violation'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION commercial.validate_refund_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target_refund_id uuid; target_payment_id uuid; actual_total numeric; overallocated boolean;
BEGIN
 IF TG_TABLE_NAME = 'refunds' THEN target_refund_id := (to_jsonb(NEW)->>'id')::uuid;
 ELSE target_refund_id := (to_jsonb(NEW)->>'refund_id')::uuid; END IF;
 SELECT payment_id INTO target_payment_id FROM commercial.refunds WHERE id = target_refund_id;
 SELECT COALESCE(sum(total_minor), 0) INTO actual_total FROM commercial.refund_items WHERE refund_id = target_refund_id;
 IF NOT EXISTS (SELECT 1 FROM commercial.refunds WHERE id = target_refund_id AND amount_minor = actual_total)
    OR NOT EXISTS (SELECT 1 FROM commercial.refund_items WHERE refund_id = target_refund_id) THEN
   RAISE EXCEPTION 'refund item allocation is incomplete' USING ERRCODE = 'check_violation';
 END IF;
 SELECT EXISTS (
   SELECT 1 FROM commercial.refund_items ri
   JOIN commercial.refunds r ON r.id = ri.refund_id
   JOIN commercial.invoice_lines il ON il.id = ri.invoice_line_id
   WHERE r.payment_id = target_payment_id AND r.status IN ('pending','succeeded')
   GROUP BY ri.invoice_line_id, il.total_minor HAVING sum(ri.total_minor) > il.total_minor
 ) INTO overallocated;
 IF overallocated THEN RAISE EXCEPTION 'refund line allocation exceeds invoice line total' USING ERRCODE = 'check_violation'; END IF;
 RETURN NULL;
END $function$
